import { useState, useEffect } from 'react';
import { fmt } from '../utils/format';
import { STORES, BRANDS } from '../utils/config';
import { useSheets } from '../hooks/useSheets';
import { erpSalesDate } from '../utils/salesCalc';

export default function QueryPage() {
  const { readAllSales, readPlatformData } = useSheets();
  const [queryType, setQueryType] = useState('sales');
  const [dateFrom,  setDateFrom]  = useState('');
  const [dateTo,    setDateTo]    = useState('');
  const [codeFilter,setCodeFilter]= useState('');
  const [brandFilter,setBrandFilter] = useState('ALL');
  const [platFilter, setPlatFilter]  = useState('ALL');
  const [results,   setResults]   = useState(null);
  const [loading,   setLoading]   = useState(false);
  const [allData,   setAllData]   = useState({ sales:[], restock:[] });

  useEffect(() => {
    // 預載資料
    Promise.all([
      readAllSales(),
      readPlatformData('inventory_log'),
    ]).then(([sales, restockRows]) => {
      // 注意：以下欄位索引對照 utils/salesCalc.js 的說明（跟 excelParser.js 實際寫入 Sheets 的欄位順序一致）。
      // 之前這裡的索引跟實際資料對不起來（例如官網把「單價」當「總金額」、經銷把「稅額」當「總金額」、
      // momo 沒有乘上數量），查詢結果的代號/數量/金額會不準，已一併修正。
      // 官網/蝦皮的 shopline_raw、shopee_raw 同時裝了 TOOLA 和拓屋兩個賣場的資料，
      // 靠每一列最後一欄的賣場標記分開（Upload.js 寫入時加上的）——之前這裡不管標記，
      // 一律當成 TOOLA，會讓拓屋官網/蝦皮的資料在「銷售平台」篩選時被誤判成 TOOLA。
      const shoplineTag = r => r[r.length-1] || 'TOOLA_SHOPLINE';
      const shopeeTag   = r => r[r.length-1] || 'TOOLA_SHOPEE';
      const salesRows = [
        ...sales.shopline.map(r => ({ id:r[0], date:r[1], platform:shoplineTag(r), brand: shoplineTag(r)==='TAKUYA_SHOPLINE'?'TAKUYA':'TOOLA', code:r[4], name:r[3], qty:Number(r[5])||0, price:Number(r[6])||0, total:Number(r[7])||0 })),
        // momo 營收用「進價」(r[5])，不是「售價」(r[6])——售價是零售價，進價才是momo實際匯給你的錢
        // （2026-09-23 已跟 Willie 確認，詳見 utils/salesCalc.js 的 calcMomoTotals 說明）。
        ...sales.momo.map(r    => ({ id:r[0], date:r[1], platform:'MOMO',           brand:'',      code:r[2], name:r[3], qty:Number(r[4])||0, price:Number(r[5])||0, total:(Number(r[5])||0)*(Number(r[4])||0) })),
        ...sales.shopee.map(r  => ({ id:r[0], date:r[1], platform:shopeeTag(r),     brand: shopeeTag(r)==='TAKUYA_SHOPEE'?'TAKUYA':'TOOLA', code:r[2], name:r[3], qty:Number(r[4])||0, price:Number(r[5])||0, total:Number(r[6])||0 })),
        // 經銷(ERP) 2026-10-25 起，date 是報表裡每一筆交易自己的真實日期（見 excelParser.js
        // 的 parseERP、utils/salesCalc.js 的 erpSalesDate 說明），欄位順序是
        // [客戶代號,客戶名稱,日期,代號,品名,數量,含稅金額]。
        ...sales.erp.map(r     => ({ id:r[0], date:erpSalesDate(r), platform:'ERP',            brand:'',      code:r[3], name:r[4], qty:Number(r[5])||0, price:Number(r[5]) ? Math.round((Number(r[6])||0)/Number(r[5])) : 0, total:Number(r[6])||0 })),
        // 手動開單金額改用「含稅金額」(r[13])，不是「小計」(r[12])——原因同上方 momo 的註解
        // 旁邊這段：未稅/含稅兩種開單方式「小計」欄位基礎不一致，詳見 utils/salesCalc.js 的
        // calcOrdersTotals 說明。
        ...sales.orders.map(r  => ({ id:r[0], date:r[1], platform:r[2]||'',        brand:'',      code:r[8], name:r[9], qty:Number(r[10])||0, price:Number(r[11])||0, total:Number(r[13])||0 })),
      ];
      const restockData = restockRows.map(r => ({
        id: `RS-${r[0]}-${r[2]}`, date:r[0], type:r[1], code:r[2], name:r[3],
        qty:Number(r[4])||0, oldStock:Number(r[5])||0, newStock:Number(r[6])||0,
        note:r[7], operator:r[8],
      }));
      setAllData({ sales: salesRows, restock: restockData });
    }).catch(() => {});
  }, []);

  const handleQuery = () => {
    setLoading(true);
    const data = queryType === 'sales' ? allData.sales : allData.restock;
    const filtered = data.filter(r => {
      // 注意：r.date 是空字串的資料（目前只有經銷 ERP）不能直接拿去跟 dateFrom/dateTo 比大小——
      // 空字串在字串比較裡一定「小於」任何有值的日期，之前的寫法會讓經銷資料只要設了
      // 起始日期就整批被篩掉，變成「一指定日期就查不到東西」。改成沒有日期的資料不受日期篩選影響。
      if (dateFrom && r.date && r.date < dateFrom) return false;
      if (dateTo   && r.date && r.date > dateTo)   return false;
      if (codeFilter) {
        const q = codeFilter.toLowerCase();
        if (!r.code?.toLowerCase().includes(q) && !r.name?.includes(codeFilter)) return false;
      }
      if (queryType === 'sales' && platFilter !== 'ALL' && r.platform !== platFilter) return false;
      return true;
    });
    setResults(filtered);
    setLoading(false);
  };

  const totalQty = results?.reduce((s,r) => s+r.qty, 0) || 0;
  const totalAmt = results?.reduce((s,r) => s+(r.total||r.qty*(r.price||0)||0), 0) || 0;

  return (
    <div>
      <div style={{ display:'flex', gap:6, marginBottom:16 }}>
        {[{ id:'sales', label:'銷貨查詢' }, { id:'restock', label:'入庫查詢' }].map(t => (
          <button key={t.id} className={`btn ${queryType===t.id?'btn-primary':'btn-ghost'}`}
            onClick={() => { setQueryType(t.id); setResults(null); }}>
            {t.label}
          </button>
        ))}
      </div>

      <div className="card mb-16">
        <div className="card-title">查詢條件</div>
        <div style={{ display:'grid', gridTemplateColumns:'repeat(3,1fr)', gap:12, marginBottom:14 }}>
          <div>
            <label className="form-label">起始日期</label>
            <input className="form-input" type="date" value={dateFrom} onChange={e=>setDateFrom(e.target.value)}/>
          </div>
          <div>
            <label className="form-label">結束日期</label>
            <input className="form-input" type="date" value={dateTo} onChange={e=>setDateTo(e.target.value)}/>
          </div>
          <div>
            <label className="form-label">產品代號 / 品名</label>
            <input className="form-input" placeholder="例：BDLN201" value={codeFilter} onChange={e=>setCodeFilter(e.target.value)}/>
          </div>
          {queryType === 'sales' && (
            <div>
              <label className="form-label">銷售平台</label>
              <select className="form-input" value={platFilter} onChange={e=>setPlatFilter(e.target.value)}>
                <option value="ALL">全部平台</option>
                {STORES.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
              </select>
            </div>
          )}
        </div>
        <div style={{ display:'flex', gap:8 }}>
          <button className="btn btn-primary" onClick={handleQuery} style={{ flex:1, justifyContent:'center' }}>◈ 開始查詢</button>
          <button className="btn btn-ghost" onClick={() => { setDateFrom(''); setDateTo(''); setCodeFilter(''); setPlatFilter('ALL'); setResults(null); }}>清除</button>
        </div>
      </div>

      {results !== null && (
        <div className="card">
          <div className="card-title">
            查詢結果
            <div style={{ display:'flex', gap:16, fontSize:14 }}>
              <span style={{ color:'var(--cyan)' }}>共 {results.length} 筆</span>
              <span style={{ color:'var(--yellow)' }}>數量：{fmt.number(totalQty)}</span>
              {queryType==='sales' && <span style={{ color:'var(--green)' }}>金額：{fmt.currency(totalAmt)}</span>}
            </div>
          </div>
          {results.length === 0
            ? <div style={{ textAlign:'center', padding:'40px', color:'var(--muted)' }}>◻ 查無符合資料</div>
            : <div className="table-wrap">
                <table>
                  <thead>
                    <tr>
                      <th>日期</th>
                      <th>{queryType==='sales'?'訂單編號':'入庫單號'}</th>
                      <th>{queryType==='sales'?'平台':'類型'}</th>
                      <th>代號</th><th>品名</th>
                      <th style={{ textAlign:'right' }}>數量</th>
                      {queryType==='sales' && <th style={{ textAlign:'right' }}>金額</th>}
                    </tr>
                  </thead>
                  <tbody>
                    {results.map((r,i) => (
                      <tr key={i}>
                        <td style={{ fontSize:17, color:'var(--muted)', whiteSpace:'nowrap' }}>{r.date}</td>
                        <td className="td-mono" style={{ color:'var(--cyan)', fontSize:17 }}>{r.id}</td>
                        <td><span style={{ fontSize:14, padding:'3px 8px', borderRadius:3, background:'rgba(0,245,255,0.1)', color:'var(--cyan)' }}>{r.platform||r.type}</span></td>
                        <td className="td-mono" style={{ color:'var(--cyan)', fontSize:17, fontWeight:700 }}>{r.code}</td>
                        <td style={{ fontSize:18, maxWidth:160, overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap' }}>{r.name}</td>
                        <td className="td-right td-mono" style={{ fontWeight:600 }}>{fmt.number(r.qty)}</td>
                        {queryType==='sales' && <td className="td-right td-mono" style={{ color:'var(--green)', fontWeight:600 }}>{fmt.currency(r.total)}</td>}
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
          }
        </div>
      )}
    </div>
  );
}
