import { useState, useEffect } from 'react';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, Cell } from 'recharts';
import { DollarSign, ShoppingCart, TrendingUp, Award } from 'lucide-react';
import { fmt, getPreviousYM } from '../utils/format';
import { useSheets } from '../hooks/useSheets';
import { buildCostMap, calcShoplineTotals, calcMomoTotals, calcShopeeTotals, calcErpTotals, calcOrdersTotals, mergeTotals, mergeUnmatched, computeUploadStatus, splitByStore, filterByMonth, filterErpByMonth } from '../utils/salesCalc';

const PLATFORM_COLORS = {
  shopline_raw: '#00c8ff', momo_raw: '#ff4488',
  shopee_raw: '#ffcc00', erp_raw: '#00e87a', orders: '#b44fff',
};

const CustomTooltip = ({ active, payload }) => {
  if (!active || !payload?.length) return null;
  return (
    <div style={{ background:'rgba(15,20,40,0.95)', border:'1px solid rgba(0,245,255,0.3)', borderRadius:6, padding:'8px 14px', boxShadow:'0 0 16px rgba(0,245,255,0.15)' }}>
      <div style={{ fontWeight:600, color:'rgba(200,200,255,0.9)', marginBottom:4, fontSize:14 }}>{payload[0].payload.name}</div>
      <div style={{ color:'#00f5ff', fontFamily:'monospace', fontWeight:700, fontSize:14 }}>{fmt.currency(payload[0].value)}</div>
    </div>
  );
};

export default function Dashboard({ setPage }) {
  const { readAllSales, readProducts, readNoSalesMarkers, readCodeMap } = useSheets();
  // 右上角可以切換月份，內容（銷售收入/成本/毛利/淨利/上傳狀態）都會隨之變動。
  // 預設看「上個月」，不是當月——當月資料才剛開始累積、報表通常還沒上傳完，
  // 用當月當預設畫面會一直顯示一堆「待上傳」，對 Willie 來說沒有參考意義。
  const [ym, setYm] = useState(() => getPreviousYM());
  const [rawSales, setRawSales] = useState({ shopline:[], momo:[], shopee:[], erp:[], orders:[] });
  const [costMap, setCostMap] = useState({});
  // 2026-10-23 新增：平台代號對應表（例如 momo 自己的商品編號 → 商品總表標準代號），
  // 見 useSheets.js 的 readCodeMap() 說明。
  const [codeMap, setCodeMap] = useState({});
  const [noSalesMarkers, setNoSalesMarkers] = useState([]);
  const [loading, setLoading] = useState(true);

  // 原始資料只在畫面第一次打開時抓一次，之後切換月份改成在畫面上重新計算，
  // 不用每次切月份都重新打一次 Sheets API（跟 PnlPage.js / SalesPage.js 同一套做法）。
  useEffect(() => {
    Promise.all([readAllSales(), readProducts(), readNoSalesMarkers(), readCodeMap()]).then(([sales, products, markers, codes]) => {
      setRawSales(sales);
      // readProducts() 已經把套組/多入組的成本從套組成分表換算好了，這裡不用再另外處理
      setCostMap(buildCostMap(products));
      setNoSalesMarkers(markers);
      setCodeMap(codes);
      setLoading(false);
    }).catch(() => setLoading(false));
  }, []); // eslint-disable-line

  const shiftMonth = (delta) => {
    setYm(p => {
      let m = p.month + delta, y = p.year;
      if (m < 1) { m = 12; y -= 1; }
      if (m > 12) { m = 1; y += 1; }
      return { year:y, month:m };
    });
  };

  // 依右上角選定的月份篩出各平台原始資料列（欄位索引對照 utils/salesCalc.js 的說明，
  // 跟 excelParser.js 實際寫入 Sheets 的欄位順序一致）。
  // 經銷(ERP) 2026-10-22 起改用 filterErpByMonth（上傳時使用者手動指定月份，
  // 舊資料仍視為沒有日期），不再永遠排除在月份檢視之外。
  const shoplineView = filterByMonth(rawSales.shopline, 1, ym.year, ym.month);
  const momoView     = filterByMonth(rawSales.momo, 1, ym.year, ym.month);
  const shopeeView   = filterByMonth(rawSales.shopee, 1, ym.year, ym.month);
  const ordersView   = filterByMonth(rawSales.orders, 1, ym.year, ym.month);
  const erpView      = filterErpByMonth(rawSales.erp, ym.year, ym.month);

  // 官網/蝦皮同時裝著 TOOLA 和拓屋兩個賣場的資料，用賣場標記分開，加總時才不會算重複。
  const shoplineByStore = splitByStore(shoplineView);
  const shopeeByStore   = splitByStore(shopeeView);
  const shoplineAll = [...(shoplineByStore.TOOLA_SHOPLINE||[]), ...(shoplineByStore.TAKUYA_SHOPLINE||[])];
  const shopeeAll   = [...(shopeeByStore.TOOLA_SHOPEE||[]),   ...(shopeeByStore.TAKUYA_SHOPEE||[])];

  // 計算各平台收入與成本（欄位對照 utils/salesCalc.js，跟 excelParser.js 實際寫入的欄位順序一致）
  // codeMap：查 costMap 之前先把平台自己的代號轉成商品總表標準代號（見上方 readCodeMap 說明）
  // ⚠ 2026-10-25 修正：手動開單選「經銷」通路的訂單，之前全部被歸到「手動開單」這個類別，
  // 完全沒有算進「經銷」的銷售數字（總營收本身沒算錯，只是分平台看的時候「經銷」被低估、
  // 「手動開單」被高估）。改成先把 ordersView 依通路拆開，「經銷」通路的部分併入 erp_，
  // 其他通路（官網/momo/蝦皮/現場/其他）維持原樣歸在 orders_／「手動開單」。
  const ordersErpView   = ordersView.filter(r => String(r[2] || '').trim() === '經銷');
  const ordersOtherView = ordersView.filter(r => String(r[2] || '').trim() !== '經銷');
  const shopline_ = calcShoplineTotals(shoplineAll, costMap, codeMap);
  const momo_     = calcMomoTotals(momoView, costMap, codeMap);
  const shopee_   = calcShopeeTotals(shopeeAll, costMap, codeMap);
  const erp_      = mergeTotals(calcErpTotals(erpView, costMap, codeMap), calcOrdersTotals(ordersErpView, costMap));
  const orders_   = calcOrdersTotals(ordersOtherView, costMap);

  const totalRevenue = shopline_.revenue + momo_.revenue + shopee_.revenue + erp_.revenue + orders_.revenue;
  const totalCost    = shopline_.cost + momo_.cost + shopee_.cost + erp_.cost + orders_.cost;
  const gross         = totalRevenue - totalCost;

  // 有賣出、但商品總表/套組成分表都查無這個代號的商品——這些的成本沒被算進 totalCost，
  // 用來提醒 Willie「毛利率看起來異常高」很可能是漏建檔，不是程式算錯
  const unmatched = mergeUnmatched(shopline_.unmatched, momo_.unmatched, shopee_.unmatched, erp_.unmatched, orders_.unmatched);
  const unmatchedRevenue = unmatched.reduce((s, u) => s + u.revenue, 0);
  const unmatchedCount = unmatched.length;

  const byPlatform = [
    { name:'經銷', value: erp_.revenue },
    { name:'momo', value: momo_.revenue },
    { name:'官網', value: shopline_.revenue },
    { name:'蝦皮', value: shopee_.revenue },
    { name:'手動開單', value: orders_.revenue },
  ].filter(p => p.value > 0).sort((a,b) => b.value - a.value);

  // 首頁摘要目前沒有納入廣告費/其他費用（那些在損益表頁面才有），
  // 所以這裡的「淨利」等於「毛利」，只代表扣掉商品成本後的數字，不是最終的公司淨利。
  const data = { revenue: totalRevenue, cost: totalCost, gross, net: gross, byPlatform, unmatchedRevenue, unmatchedCount };

  // 「報表上傳狀態」改成跟上面revenue/cost一樣，依右上角選定的月份去判斷（預設上個月），
  // 不是寫死抓系統當下的年月。也一併套用「本月無銷貨資料」標記，跟報表上傳頁一致。
  const markerSet = new Set(noSalesMarkers.map(m => `${m.storeId}|${m.ym}`));
  const status = computeUploadStatus(rawSales, ym.year, ym.month, markerSet);
  const doneCount = Object.values(status).filter(v => v.done).length;
  const totalStores = 6;
  const periodLabel = `${ym.year}年${ym.month}月`;

  const metrics = [
    { label:`${periodLabel}銷售收入`, value: data.revenue, change: null, cls:'cyan', Icon: DollarSign },
    { label:'銷貨成本合計', value: data.cost,    change: null, cls:'pink', Icon: ShoppingCart },
    { label:'毛利 ／ 毛利率', value: data.gross, sub: data.revenue > 0 ? `毛利率 ${fmt.pct(data.gross/data.revenue)}` : '–', cls:'green', Icon: TrendingUp },
    { label:`${periodLabel}淨利`,       value: data.net,   sub: data.revenue > 0 ? `淨利率 ${fmt.pct(data.net/data.revenue)}` : '–', cls:'yellow', Icon: Award },
  ];

  return (
    <div>
      <div className="flex-between mb-16">
        <div style={{ fontSize:14, color:'var(--muted)' }}>
          ◈ 右上角可以切換月份，下面的數字和上傳狀態會跟著變動（預設顯示上個月）
        </div>
        <div style={{ display:'flex', alignItems:'center', gap:8 }}>
          <button className="btn btn-sm btn-ghost" onClick={() => shiftMonth(-1)}>‹</button>
          <span style={{ fontSize:14, color:'var(--text)', minWidth:78, textAlign:'center', fontFamily:'var(--mono)' }}>
            {ym.year}年{ym.month}月
          </span>
          <button className="btn btn-sm btn-ghost" onClick={() => shiftMonth(1)}>›</button>
        </div>
      </div>

      {loading && <div style={{ textAlign:'center', padding:'40px', color:'var(--muted)', fontSize:14 }}>載入中…</div>}

      {!loading && data.unmatchedCount > 0 && (
        <div style={{ background:'rgba(255,196,0,0.08)', border:'1px solid rgba(255,196,0,0.35)', borderRadius:8, padding:'10px 14px', marginBottom:16, fontSize:13, color:'var(--yellow, #f5c400)' }}>
          ⚠ 有 {data.unmatchedCount} 個商品代號有賣出（共 {fmt.currency(data.unmatchedRevenue)} 營收），但商品總表/套組成分表都查無資料，這些的成本沒有被算進上面的「銷貨成本」，毛利率可能被高估。
          到「銷貨總表」頁面可以看到完整清單，補上這些代號的成本資料後數字才會準確。
        </div>
      )}

      <div className="metrics-grid" style={{ display:'grid', gridTemplateColumns:'repeat(2,1fr)', gap:12, marginBottom:20 }}>
        {metrics.map(({ label, value, change, sub, cls, Icon }) => (
          <div key={label} className={`metric-card metric-card--${cls}`}>
            <div className="metric-header">
              <span className="metric-label">{label}</span>
              <Icon size={18} className="metric-icon"/>
            </div>
            <div className="metric-value">{fmt.currency(value)}</div>
            {sub && <div className="metric-change" style={{ color:'var(--cyan)', fontWeight:600 }}>{sub}</div>}
            {change !== null && (
              <div className={`metric-change ${change >= 0 ? 'positive' : 'negative'}`}>
                {change >= 0 ? '↗' : '↘'} {fmt.pct(Math.abs(change))} 較上月
              </div>
            )}
          </div>
        ))}
      </div>

      <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:16, marginBottom:20 }}>
        {/* 各平台銷售金額 */}
        <div className="card">
          <div className="card-title">各平台銷售金額 <span>{periodLabel}</span></div>
          {data.byPlatform.length === 0
            ? <div style={{ textAlign:'center', padding:'40px 0', color:'var(--muted)', fontSize:14 }}>◻ 尚無資料，請先上傳報表</div>
            : <ResponsiveContainer width="100%" height={180}>
                <BarChart data={data.byPlatform} layout="vertical" margin={{ left:4, right:16, top:4, bottom:4 }}>
                  <XAxis type="number" hide/>
                  <YAxis type="category" dataKey="name" width={44} tick={{ fontSize:13, fill:'rgba(200,200,255,0.85)', fontFamily:'monospace' }}/>
                  <Tooltip content={<CustomTooltip/>} cursor={{ fill:'rgba(0,245,255,0.06)' }}/>
                  <Bar dataKey="value" radius={[0,3,3,0]}>
                    {data.byPlatform.map(e => (
                      <Cell key={e.name} fill={
                        e.name==='經銷'?'#00e87a': e.name==='momo'?'#ff4488':
                        e.name==='官網'?'#00c8ff': e.name==='蝦皮'?'#ffcc00':'#b44fff'
                      }/>
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
          }
        </div>

        {/* 報表上傳狀態 */}
        <div className="card">
          <div className="card-title">
            報表上傳狀態 <span style={{ color:'var(--muted)', fontWeight:400 }}>（{periodLabel}）</span>
            <span style={{ color: doneCount === totalStores ? 'var(--green)' : 'var(--yellow)' }}>
              △ {doneCount}/{totalStores} 已上傳
            </span>
          </div>
          {['TOOLA_SHOPLINE','TOOLA_SHOPEE','MOMO','TAKUYA_SHOPEE','TAKUYA_SHOPLINE','ERP'].map(id => {
            const labels = { TOOLA_SHOPLINE:'TOOLA_SHOPLINE 報表', TOOLA_SHOPEE:'TOOLA_SHOPEE 報表', MOMO:'MOMO 報表', TAKUYA_SHOPEE:'TAKUYA_SHOPEE 報表', TAKUYA_SHOPLINE:'TAKUYA_SHOPLINE 報表', ERP:'ERP 報表' };
            const s = status[id] || {};
            const done = s.done;
            return (
              <div key={id} onClick={() => setPage('upload')}
                style={{ display:'flex', alignItems:'center', gap:10, padding:'8px 0', borderBottom:'1px solid var(--border)', cursor:'pointer' }}>
                <div style={{ width:8, height:8, borderRadius:'50%', background: done ? 'var(--green)' : 'var(--muted)', boxShadow: done ? '0 0 6px var(--green)' : 'none', flexShrink:0 }}/>
                <div>
                  <div style={{ fontSize:14, fontWeight:600 }}>{labels[id]}</div>
                  <div style={{ fontSize:12, color: done ? 'var(--green)' : 'var(--yellow)' }}>
                    {done
                      ? (s.noSalesMarked ? '－ 本月無銷貨資料' : s.approximate ? `✓ 有上傳過（此報表無日期，無法確認是否為${periodLabel}）` : '✓ 已匯入')
                      : '待上傳 － 點擊前往'}
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* 本期損益摘要 */}
      <div className="card">
        <div className="card-title">損益摘要 <span>{periodLabel}</span></div>
        {[
          { label:'銷貨收入', value: data.revenue, color:'var(--cyan)',   pct: 1 },
          { label:'銷貨成本', value: data.cost,    color:'var(--pink)',   pct: data.revenue > 0 ? data.cost/data.revenue : 0 },
          { label:'毛利',     value: data.gross,   color:'var(--green)',  pct: data.revenue > 0 ? data.gross/data.revenue : 0 },
        ].map(({ label, value, color, pct }) => (
          <div key={label} style={{ marginBottom:12 }}>
            <div style={{ display:'flex', justifyContent:'space-between', marginBottom:4 }}>
              <span style={{ fontSize:14, color:'var(--muted)' }}>{label}</span>
              <span style={{ fontSize:14, color, fontFamily:'var(--mono)', fontWeight:600 }}>{fmt.currency(value)}</span>
            </div>
            <div style={{ height:4, background:'var(--bg3)', borderRadius:2 }}>
              <div style={{ height:'100%', width:`${Math.min(100, pct*100)}%`, background:color, borderRadius:2, boxShadow:`0 0 6px ${color}60`, transition:'width .5s' }}/>
            </div>
          </div>
        ))}
        <div style={{ marginTop:16, padding:'12px 16px', background: data.net >= 0 ? 'rgba(0,255,159,0.08)' : 'rgba(255,0,110,0.08)', borderRadius:4, border:`1px solid ${data.net >= 0 ? 'rgba(0,255,159,0.3)' : 'rgba(255,0,110,0.3)'}`, display:'flex', justifyContent:'space-between', alignItems:'center' }}>
          <div>
            <div style={{ fontSize:13, color: data.net >= 0 ? 'var(--green)' : 'var(--pink)', letterSpacing:1 }}>{periodLabel}淨利</div>
            <div style={{ fontSize:12, color: data.net >= 0 ? 'var(--green)' : 'var(--pink)', opacity:0.7 }}>淨利率 {data.revenue > 0 ? fmt.pct(data.net/data.revenue) : '–'}</div>
          </div>
          <div style={{ fontSize:26, fontWeight:700, color: data.net >= 0 ? 'var(--green)' : 'var(--pink)', fontFamily:'var(--title)', textShadow: `0 0 16px ${data.net >= 0 ? 'var(--green)' : 'var(--pink)'}60` }}>
            {fmt.currency(data.net)}
          </div>
        </div>
      </div>
    </div>
  );
}
