import * as XLSX from 'xlsx';

// ── Barcode → 標準產品代號對照表 ───────────────────────────────
// 當蝦皮商品選項貨號填的是 Barcode 而不是產品代號時，在此轉換
const BARCODE_TO_CODE = {
  '4711263761459': 'BDLN201',  // 麗容酵素入浴劑 880g
  '4711263333335': 'BDLN101',  // 麗容酵素入浴劑 600g
  '4711263669991': 'BDLN301',  // 蔬果奶瓶洗滌劑 500ml
  '4711263663333': 'BDLN401',  // 抗菌防螨洗衣精 1000ml
  '4711035553015': 'BDTL101',  // 多樂 B5 多效保濕修護霜
  '4711035550700': 'BDTL201',  // 多樂 嬰幼兒洗沐泡泡露－英國梨
  '4711035550724': 'BDTL301',  // 多樂 嬰幼兒多用途保濕慕絲－英國梨
  '4711035550731': 'BDTL401',  // 多樂 嬰幼兒多用途保濕慕絲－純淨無香
  '4711035550038': 'BDTL501',  // 極韌安全 無毒防護角四入－粉直角
  '4711035550014': 'BDTL601',  // 極韌安全 無毒防護角四入－棕圓角
  '4711035550021': 'BDTL701',  // 極韌安全 無毒防護角四入－棕直角
  '4711035550045': 'BDTL801',  // 極韌安全 無毒防護角四入－白直角
  '4711035550137': 'BDTL901',  // 太陽便盆 多階段學習馬桶－藍
  '4711035550113': 'BDTL1001', // 太陽便盆 多階段學習馬桶－粉
  '4711035550120': 'BDTL1101', // 太陽便盆 多階段學習馬桶墊－藍
  '4711035550106': 'BDTL1201', // 太陽便盆 多階段學習馬桶墊－粉
};

// 將任意代號標準化（Barcode → 產品代號，並去除空格）
function normalizeCode(raw) {
  if (!raw) return '';
  const cleaned = String(raw).trim().replace(/\s+/g, '');
  return BARCODE_TO_CODE[cleaned] || cleaned;
}

// ⚠ 2026-10-25 新增：把 Excel 儲存格讀出來的數字字串轉成真正的數字。
// sheetToRows() 用 raw:false 讀 Excel，如果儲存格格式有設千分位逗號（例如 3078 顯示成
// "3,078"），XLSX 套件會把它讀成字串 "3,078"，直接 Number("3,078") 會得到 NaN，
// 再被程式到處都有的 `|| 0` 接住，變成悄悄算成 0——不會報錯、不會中斷上傳，
// 但營收/數量會嚴重低估。這次從經銷(ERP)報表實測發現這個問題（已用 Node.js
// 的 xlsx 套件直接模擬證實），四個平台的解析函式都統一改用這個函式讀數字，
// 不要再直接用 Number()。
function toNum(val) {
  if (val === '' || val === null || val === undefined) return 0;
  if (typeof val === 'number') return val;
  const cleaned = String(val).trim().replace(/,/g, '');
  if (!cleaned) return 0;
  const n = Number(cleaned);
  return isNaN(n) ? 0 : n;
}

// ── 通用：讀取 Excel ──────────────────────────────────────────
export function parseExcel(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const wb = XLSX.read(e.target.result, { type: 'array', cellDates: true });
        resolve(wb);
      } catch (err) { reject(err); }
    };
    reader.onerror = reject;
    reader.readAsArrayBuffer(file);
  });
}

function sheetToRows(ws) {
  return XLSX.utils.sheet_to_json(ws, { header: 1, defval: '', raw: false });
}

function findIdx(headers, keywords) {
  for (const kw of keywords) {
    const i = headers.findIndex(h => String(h).includes(kw));
    if (i !== -1) return i;
  }
  return -1;
}

// ── 自動偵測平台 ───────────────────────────────────────────────
export function detectPlatform(wb) {
  const sheets = wb.SheetNames;
  const ws = wb.Sheets[sheets[0]];
  const rows = sheetToRows(ws);
  const header = (rows[0] || []).join(',');

  // 蝦皮：有「商品選項貨號」或「蝦皮商品編碼」
  if (header.includes('商品選項貨號') || header.includes('蝦皮商品編碼')) return '蝦皮';
  // 官網 Shopline：有「商品貨號」且有「訂單號碼」
  if ((header.includes('商品貨號') || header.includes('商品結帳價')) && header.includes('訂單')) return '官網';
  // momo：格式A（有訂單編號+進價含稅）或格式B（品號+進價+數量(訂購-取消)）
  if (header.includes('品號') && (header.includes('進價') || header.includes('數量(訂購-取消)'))) return 'momo';
  // 經銷 ERP：有客戶代號或銷貨明細特徵
  if (header.includes('客戶代號') || header.includes('銷貨明細') || header.includes('BTB')) return '經銷';
  // 嘗試從工作表名稱判斷
  if (sheets.some(s => s.includes('orders'))) return '蝦皮';
  if (sheets.some(s => s.includes('Sales'))) return '官網';
  return null;
}

// ── 官網 (Shopline) ────────────────────────────────────────────
export function parseShopline(wb) {
  const ws = wb.Sheets['Sales'] || wb.Sheets[wb.SheetNames[0]];
  const rows = sheetToRows(ws);
  if (rows.length < 2) return { rows: [], summary: {} };

  const headers = rows[0];
  const iOrder  = findIdx(headers, ['訂單號碼']);
  const iDate   = findIdx(headers, ['訂單日期']);
  const iStatus = findIdx(headers, ['訂單狀態']);
  const iSku    = findIdx(headers, ['商品貨號']);
  const iName   = findIdx(headers, ['商品名稱']);
  const iQty    = findIdx(headers, ['數量']);
  const iPrice  = findIdx(headers, ['商品結帳價']);
  const iTotal  = findIdx(headers, ['付款總金額']);

  const validStatuses = ['已完成', '已確認'];
  const result = [];

  for (let i = 1; i < rows.length; i++) {
    const r = rows[i];
    if (!validStatuses.includes(String(r[iStatus] || ''))) continue;
    const sku = normalizeCode(r[iSku]);
    if (!sku) continue;

    result.push([
      String(r[iOrder] || '').trim(),
      formatDate(r[iDate]),
      String(r[iStatus] || '').trim(),
      String(r[iName] || '').trim(),
      sku,
      toNum(r[iQty]),
      toNum(r[iPrice]),
      toNum(r[iTotal]),
    ]);
  }

  // 注意：這裡的營收預覽要用「付款總金額」(r[7])，不能用「商品結帳價 × 數量」(r[6]*r[5])。
  // 一張訂單如果有主商品＋加購商品，Shopline 匯出時常常整張訂單的付款總金額只會算在主商品那一列，
  // 加購商品那一列的付款總金額是 0（實際金額已經包含在主商品那一列了，不是加購商品真的免費）。
  // 如果用「單價×數量」重算，加購商品那一列會被算出一個金額，導致上傳預覽看到的營收
  // 比之後在銷貨總表/首頁看到的營收還要高（銷貨總表用的是真正的付款總金額加總）。
  const revenue = result.reduce((s, r) => s + (r[7] || 0), 0);
  return { rows: result, summary: { platform: '官網', count: result.length, revenue } };
}

// ── momo ──────────────────────────────────────────────────────
// 支援兩種格式：
// 格式A（訂單明細）：有訂單編號、轉單日、售價(含稅)
// 格式B（廠商進貨彙整）：品號、商品原廠編號、進價、數量(訂購-取消)
export function parseMomo(wb) {
  const ws = wb.Sheets[wb.SheetNames[0]];
  const rows = sheetToRows(ws);
  if (rows.length < 2) return { rows: [], summary: {} };

  const headers = rows[0];

  // 偵測格式
  const hasOrderNo = findIdx(headers, ['訂單編號']) !== -1;
  const hasQtyCancel = findIdx(headers, ['數量(訂購-取消)', '數量']) !== -1;

  if (hasOrderNo) {
    // 格式A：訂單明細表
    const iOrder  = findIdx(headers, ['訂單編號']);
    const iDate   = findIdx(headers, ['轉單日']);
    const iCode   = findIdx(headers, ['品號']);
    const iName   = findIdx(headers, ['品名']);
    const iQty    = findIdx(headers, ['數量']);
    const iCost   = findIdx(headers, ['進價(含稅)', '進價']);
    const iPrice  = findIdx(headers, ['售價(含稅)', '售價']);
    const iReturn = findIdx(headers, ['退貨原因']);
    const result  = [];

    for (let i = 1; i < rows.length; i++) {
      const r = rows[i];
      if (!String(r[iOrder] || '').trim()) continue;
      const returnReason = String(r[iReturn] || '').trim();
      if (returnReason && returnReason !== 'nan' && returnReason !== '-') continue;
      const code = normalizeCode(r[iCode]);
      result.push([
        String(r[iOrder] || '').trim(),
        formatDate(r[iDate]),
        code,
        String(r[iName] || '').trim(),
        toNum(r[iQty]),
        toNum(r[iCost]),   // 進價（索引5）＝ momo 實際匯給你的錢，2026-09-23 已跟 Willie 確認
        toNum(r[iPrice]), // 售價（索引6）＝ momo 賣給消費者的零售價，不是你收到的錢，只留著參考
      ]);
    }
    // 上傳預覽的營收用「進價」(r[5])，不是「售價」(r[6])——這裡之前用售價算，
    // 會讓上傳當下看到的預覽營收比之後銷貨總表/首頁看到的（用進價算）還要高。
    const revenue = result.reduce((s, r) => s + r[5] * r[4], 0);
    return { rows: result, summary: { platform: 'momo', count: result.length, revenue } };

  } else {
    // 格式B：廠商進貨彙整表（品號、進價、數量）
    const iCode     = findIdx(headers, ['品號']);
    const iBarcode  = findIdx(headers, ['商品原廠編號']);
    const iName     = findIdx(headers, ['品名']);
    const iSpec     = findIdx(headers, ['規格']);
    const iPrice    = findIdx(headers, ['進價']);
    const iQty      = findIdx(headers, ['數量(訂購-取消)', '數量']);
    const iReturn   = findIdx(headers, ['客退數量']);
    const result    = [];

    for (let i = 1; i < rows.length; i++) {
      const r = rows[i];
      const momoCode = String(r[iCode] || '').trim();
      if (!momoCode) continue;

      // 優先用 Barcode 轉換標準代號，沒有就用品號
      const barcode = String(r[iBarcode] || '').trim();
      const code    = normalizeCode(barcode) !== barcode ? normalizeCode(barcode) : normalizeCode(momoCode);

      const qty       = toNum(r[iQty]);
      const returnQty = toNum(r[iReturn]);
      const netQty    = qty - returnQty;
      if (netQty <= 0) continue;

      const price   = toNum(r[iPrice]);  // 進價 = momo 結算單價
      const name    = String(r[iName] || '').trim();
      const spec    = String(r[iSpec] || '').trim();

      result.push([
        `MOMO-${momoCode}-${i}`,  // 虛擬訂單編號
        '',                         // 無日期
        code,
        spec ? `${name}－${spec}` : name,
        netQty,
        price,                      // 進價作為成本參考
        price,                      // 進價也作為結算收入（momo進價即為你的售出金額）
      ]);
    }
    const revenue = result.reduce((s, r) => s + r[5] * r[4], 0);
    return { rows: result, summary: { platform: 'momo', count: result.length, revenue } };
  }
}

// ── 蝦皮 (根據實際報表結構更新) ───────────────────────────────
// 欄位：訂單編號[0] / 訂單狀態[1] / 退貨退款狀態[3] / 訂單成立日期[5]
//       商品名稱[24] / 商品選項貨號[32] / 主商品貨號[31]
//       數量[33] / 退貨數量[34] / 商品活動價格[30] / 商品原價[29]
export function parseShopee(wb) {
  // 支援多工作表（TAKUYA 報表有 07、08 等多個月份分頁）
  // 合併所有工作表的資料
  const allRows = [];
  let headers = null;

  for (const sheetName of wb.SheetNames) {
    const ws = wb.Sheets[sheetName];
    const rows = sheetToRows(ws);
    if (rows.length < 2) continue;

    // 第一個工作表取 headers
    if (!headers) {
      headers = rows[0];
    }
    // 從第二列開始取資料（跳過標題列）
    allRows.push(...rows.slice(1));
  }

  if (!headers || allRows.length === 0) return { rows: [], summary: {} };

  const iOrder      = findIdx(headers, ['訂單編號']);
  const iStatus     = findIdx(headers, ['訂單狀態']);
  const iReturnSt   = findIdx(headers, ['退貨 / 退款狀態', '退貨/退款狀態']);
  const iDate       = findIdx(headers, ['訂單成立日期', '付款時間']);
  const iName       = findIdx(headers, ['商品名稱']);
  const iMainCode   = findIdx(headers, ['主商品貨號']);
  const iOptCode    = findIdx(headers, ['商品選項貨號']);
  const iShopeeCode = findIdx(headers, ['蝦皮商品編碼 (商品ID_規格ID)', '蝦皮商品編碼']);
  const iQty        = findIdx(headers, ['數量']);
  const iReturnQty  = findIdx(headers, ['退貨數量']);
  const iPrice      = findIdx(headers, ['商品活動價格', '商品原價']);
  const iTotalPaid  = findIdx(headers, ['買家總支付金額', '買家支付金額']);
  const iOptName    = findIdx(headers, ['商品選項名稱']);

  const result = [];
  const seenOrders = new Set();

  for (const r of allRows) {
    const orderId = String(r[iOrder] || '').trim();
    if (!orderId) continue;

    // 只取已完成訂單
    const status = String(r[iStatus] || '').trim();
    if (status && !['已完成', 'Completed'].includes(status)) continue;

    // 排除退貨
    const returnSt = String(r[iReturnSt] || '').trim();
    if (returnSt && !['', '-', 'None', 'NaN'].includes(returnSt)) continue;

    // 退貨數量扣除
    const qty       = toNum(r[iQty]);
    const returnQty = toNum(r[iReturnQty]);
    const netQty    = qty - returnQty;
    if (netQty <= 0) continue;

    // 產品代號：主商品貨號 > 商品選項貨號 > 蝦皮商品編碼
    let rawCode = String(r[iMainCode] || '').trim();
    if (!rawCode || rawCode === 'NaN') rawCode = String(r[iOptCode] || '').trim();
    if (!rawCode || rawCode === 'NaN') rawCode = String(r[iShopeeCode] || '').trim();

    const code = normalizeCode(rawCode) || rawCode;
    const name = String(r[iName] || '').trim();
    const optName = String(r[iOptName] || '').trim();
    const price = toNum(r[iPrice]);
    const totalPaid = toNum(r[iTotalPaid]) || price * netQty;

    result.push([
      orderId,
      formatDate(r[iDate]),
      code,
      optName ? `${name}－${optName}` : name,
      netQty,
      price,
      totalPaid,
    ]);
  }

  const revenue = result.reduce((s, r) => s + (r[6] || 0), 0);
  return { rows: result, summary: { platform: '蝦皮', count: result.length, revenue } };
}

// ⚠ 2026-10-25 重寫：這份函式原本是照一種「一列一筆、只有8欄」的簡化格式寫的
// （[客戶代號,客戶名稱,代號,品名,數量,未稅金額,稅額,含稅總額]），但 Willie 實際上傳的
// 經銷報表（銷貨明細表(客戶)）完全不是這個格式——是階層式的：客戶代號/日期/單號只出現在
// 這筆交易的第一列，底下同一筆交易的其他品項列是空白延續；欄位順序也完全不同，實際是
// [客戶代號, 客戶簡稱, 銷退貨日期, 銷退貨單號, 預收日期, 項次, 產品代號, 品名規格,
//  銷退貨量, 單位, 出貨單價, 銷退貨總額, 含稅金額]（共13欄）。
// 用舊邏輯（抓第0、2欄當代號）去跑這份報表，一筆資料都抓不到（已實測確認 0 筆），
// Google Sheets 後台 erp_raw 現有的資料也因此欄位對錯位置、金額大多顯示 0——這次一併修正。
//
// 這份報表本身就有「銷退貨日期」，是每一筆交易自己的真實日期，不再需要上傳時
// 由使用者手動選一個月份套用到整份報表（那是舊格式沒有日期欄位時的退而求其次做法）。
//
// 另外這份報表會有「現金收款折現」這類不是商品、但要算進營收扣減的列（代號通常是
// 「ZZZ」，金額是負的，用來表示客戶提早付款的折扣）——這種列的「代號」不是 BD/NEW
// 開頭，用特殊代號 __ADJUST__ 標記，calcErpTotals 看到這個代號只會把金額算進營收，
// 不會拿去查商品成本，也不會被誤判成「查無資料」的商品代號。
export function parseERP(wb) {
  const ws = wb.Sheets[wb.SheetNames[0]];
  const rows = sheetToRows(ws);

  const result = [];
  let currentClientCode = '';
  let currentClient = '';
  let currentDate = '';

  for (let i = 0; i < rows.length; i++) {
    const r = rows[i];
    const vals = r.map(v => String(v || '').trim());

    // 客戶列：第0欄是 BTBxxxxxx 開頭的客戶代號（只出現在這個客戶第一筆交易的第一列）
    if (vals[0] && vals[0].startsWith('BTB')) {
      currentClientCode = vals[0];
      currentClient = vals[1] || '';
    }

    // 銷退貨日期（第2欄）：只出現在每一筆交易（單號）的第一列，底下的品項列是空白，
    // 沿用同一筆交易最後看到的日期。
    if (vals[2]) {
      const d = formatDate(vals[2]);
      if (d) currentDate = d;
    }

    const code = vals[6];       // 產品代號（第6欄，不是第0或第2欄——這是這次修正的關鍵）
    if (!code) continue;        // 小計列／總計列這一欄是空白，跳過

    const qty      = toNum(vals[8]);  // 銷退貨量（第8欄）——2026-10-25 改用 toNum()：這份報表的
                                       // 數字欄位是千分位逗號格式（例如 "3,078"），直接 Number()
                                       // 會變成 NaN 再被 || 0 吃掉，整批金額悄悄算成 0（已實測確認）。
    const totalAmt = toNum(vals[12]); // 含稅金額（第12欄，實測跟「銷退貨總額」第11欄永遠相同，
                                       // 這份報表沒有另外拆未稅/稅額，不再硬湊假欄位）

    if (code.startsWith('BD') || code.startsWith('NEW')) {
      if (qty !== 0) {
        result.push([
          currentClientCode,
          currentClient,
          currentDate,
          normalizeCode(code),
          vals[7] || '',   // 品名規格
          qty,
          totalAmt,
        ]);
      }
    } else if (totalAmt !== 0) {
      // 不是正常商品代號的列（例如「ZZZ」現金收款折現）——不計數量，只把金額算進營收，
      // 不然加總會跟報表本身的客戶小計/報表總計對不起來。
      result.push([
        currentClientCode,
        currentClient,
        currentDate,
        '__ADJUST__',
        vals[7] || '折讓/折扣',
        0,
        totalAmt,
      ]);
    }
  }

  const revenue = result.reduce((s, r) => s + (r[6] || 0), 0);
  return { rows: result, summary: { platform: '經銷', count: result.length, revenue } };
}

// ── 日期格式化 ─────────────────────────────────────────────────
function formatDate(val) {
  if (!val) return '';
  const s = String(val);
  // 已是 YYYY-MM-DD 或 YYYY/MM/DD 格式
  if (/^\d{4}[-\/]\d{2}[-\/]\d{2}/.test(s)) return s.slice(0, 10).replace(/\//g, '-');
  // Excel 數字型日期
  if (!isNaN(Number(val))) {
    try {
      const d = XLSX.SSF.parse_date_code(Number(val));
      if (d) return `${d.y}-${String(d.m).padStart(2,'0')}-${String(d.d).padStart(2,'0')}`;
    } catch { return s; }
  }
  return s.slice(0, 10);
}

// ── 主入口：自動解析 ───────────────────────────────────────────
export async function autoParsePlatform(file) {
  let wb;
  try {
    wb = await parseExcel(file);
  } catch (e) {
    return { platform: null, error: `檔案讀取失敗：${e.message}` };
  }

  const platform = detectPlatform(wb);
  if (!platform) {
    return { platform: null, error: '無法辨識平台格式，請確認欄位是否正確（官網/momo/蝦皮/經銷）' };
  }

  let result;
  try {
    switch (platform) {
      case '官網': result = parseShopline(wb); break;
      case 'momo': result = parseMomo(wb); break;
      case '蝦皮': result = parseShopee(wb); break;
      case '經銷': result = parseERP(wb); break;
      default: return { platform: null, error: '未知平台' };
    }
  } catch (e) {
    return { platform, error: `解析失敗：${e.message}` };
  }

  return { platform, ...result };
}
